SELECT user_id FROM sys_user
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
FOR UPDATE

SELECT * FROM wf_agent_setting
WHERE tenant_id = #{tenantId} AND principal_user_id = #{userId}
FOR UPDATE

SELECT DISTINCT principal_user_id FROM wf_agent_setting
WHERE tenant_id = #{tenantId} AND principal_user_id > #{afterUserId}
ORDER BY principal_user_id LIMIT #{limit}

